namespace ws {
    using FileDescriptor = int;
    inline constexpr FileDescriptor invalid_file_descriptor {-1};

    std::string StringToLower(std::string str) noexcept;
    std::string StringToUpper(std::string str) noexcept;
    std::string ReplaceAllSubstring(std::string_view str, std::string_view from,
                                    std::string_view to) noexcept;
    std::vector<std::string> SplitString(const std::string& str,
                                         const std::regex& pattern) noexcept;
    std::vector<std::string> SplitStringToLines(const std::string& str) noexcept;

    YAML::Node LoadYamlString(
        std::string_view str,
        std::initializer_list<std::string_view> required_fields = {});
    void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node,
                                     std::string_view field);

    constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept;
    void SetFileDescriptorAsNonblocking(FileDescriptor fd);

    [[noreturn]] void ThrowLastSystemError();
    std::uint32_t CurrentThreadId() noexcept;

    void Backtrace(std::vector<std::string>& stack, std::size_t size,
                   std::size_t skip = 0) noexcept;
    std::string Backtrace(std::size_t size, std::size_t skip = 0,
                          std::string_view prefix = "") noexcept;

    template <typename T, typename... Args>
    class Singleton {
    public:
        template <Args... args>
        static T& Instance() noexcept;
    };

    template <typename T, typename... Args>
    class SingletonPtr {
    public:
        template <Args... args>
        static std::shared_ptr<T> Instance() noexcept;
    };

    template <typename T, typename Cleaner = std::function<void(T)>>
    requires std::is_invocable_v<Cleaner, T>
    class RAII {
    public:
        explicit RAII(T obj, Cleaner cleaner) noexcept;
        ~RAII() noexcept;
        const T& Object() const noexcept;
    private:
        T obj_;
        Cleaner cleaner_;
    };

    class MappedReadOnlyFile {
    public:
        MappedReadOnlyFile() noexcept;
        ~MappedReadOnlyFile() noexcept;
        std::byte* Map(std::string path);
        void Unmap() noexcept;
        std::size_t Size() const noexcept;
        std::byte* Data() const noexcept;
        std::string_view Path() const noexcept;
    private:
        void Check();
        std::string path_;
        struct stat stat_ {};
        std::byte* data_ {nullptr};
    };

    template <typename T, typename U, typename Ret = T>
    concept Addable = requires(T t, U u) {
        { t + u } -> std::convertible_to<Ret>;
    };
}

#include "util.h"
#include <fmt/format.h>
#include <yaml-cpp/yaml.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <cstring>
#include <system_error>

namespace ws {
    std::string StringToLower(std::string str) noexcept {
        for (auto& c : str) {
            c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        }
        return str;
    }

    std::string StringToUpper(std::string str) noexcept {
        for (auto& c : str) {
            c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
        }
        return str;
    }

    std::string ReplaceAllSubstring(std::string_view str, std::string_view from,
                                    std::string_view to) noexcept {
        if (from.empty()) return std::string(str);
        std::string result;
        size_t start_pos = 0;
        size_t found_pos;
        while ((found_pos = str.find(from, start_pos)) != std::string::npos) {
            result.append(str.substr(start_pos, found_pos - start_pos));
            result.append(to);
            start_pos = found_pos + from.length();
        }
        result.append(str.substr(start_pos));
        return result;
    }

    std::vector<std::string> SplitString(const std::string& str,
                                         const std::regex& pattern) noexcept {
        std::vector<std::string> result;
        std::sregex_token_iterator it(str.begin(), str.end(), pattern, -1);
        std::sregex_token_iterator end;
        for (; it != end; ++it) {
            result.emplace_back(*it);
        }
        return result;
    }

    std::vector<std::string> SplitStringToLines(const std::string& str) noexcept {
        std::vector<std::string> result;
        size_t start = 0;
        size_t end = str.find('\n');
        while (end != std::string::npos) {
            result.push_back(str.substr(start, end - start));
            start = end + 1;
            end = str.find('\n', start);
        }
        if (start < str.length()) {
            result.push_back(str.substr(start));
        }
        return result;
    }

    YAML::Node LoadYamlString(
        std::string_view str,
        std::initializer_list<std::string_view> required_fields) {
        try {
            YAML::Node node = YAML::Load(str);
            for (const auto& field : required_fields) {
                if (!node[field.data()]) {
                    throw std::runtime_error(fmt::format("Required field '{}' not found", field));
                }
                ThrowIfYamlFieldIsNotScalar(node, field);
            }
            return node;
        } catch (const YAML::Exception& e) {
            throw std::runtime_error(fmt::format("Failed to parse YAML: {}", e.what()));
        }
    }

    void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node,
                                     std::string_view field) {
        if (!node[field.data()].IsScalar()) {
            throw std::runtime_error(fmt::format("Field '{}' is not a scalar", field));
        }
    }

    constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept {
        return fd >= 0;
    }

    void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
        int flags = fcntl(fd, F_GETFL, 0);
        if (flags == -1) {
            ThrowLastSystemError();
        }
        if (fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) {
            ThrowLastSystemError();
        }
    }

    [[noreturn]] void ThrowLastSystemError() {
        throw std::system_error(errno, std::generic_category());
    }

    std::uint32_t CurrentThreadId() noexcept {
        return static_cast<std::uint32_t>(pthread_self());
    }

    void Backtrace(std::vector<std::string>& stack, std::size_t size,
                   std::size_t skip) noexcept {
        void* frames[100];
        int num_frames = backtrace(frames, static_cast<int>(std::min(size, static_cast<size_t>(100))));
        char** symbols = backtrace_symbols(frames, num_frames);
        for (int i = skip; i < num_frames; ++i) {
            stack.emplace_back(symbols[i]);
        }
        free(symbols);
    }

    std::string Backtrace(std::size_t size, std::size_t skip,
                          std::string_view prefix) noexcept {
        std::vector<std::string> stack;
        Backtrace(stack, size, skip);
        std::string result;
        for (const auto& frame : stack) {
            if (!result.empty()) result += "\n";
            result += prefix;
            result += frame;
        }
        return result;
    }

    template <typename T, typename... Args>
    template <Args... args>
    T& Singleton<T, Args...>::Instance() noexcept {
        static T instance(std::forward<Args>(args)...);
        return instance;
    }

    template <typename T, typename... Args>
    template <Args... args>
    std::shared_ptr<T> SingletonPtr<T, Args...>::Instance() noexcept {
        static std::shared_ptr<T> instance = std::make_shared<T>(std::forward<Args>(args)...);
        return instance;
    }

    template <typename T, typename Cleaner>
    requires std::is_invocable_v<Cleaner, T>
    RAII<T, Cleaner>::RAII(T obj, Cleaner cleaner) noexcept : obj_(std::move(obj)), cleaner_(cleaner) {}

    template <typename T, typename Cleaner>
    requires std::is_invocable_v<Cleaner, T>
    RAII<T, Cleaner>::~RAII() noexcept {
        if (cleaner_) cleaner_(obj_);
    }

    template <typename T, typename Cleaner>
    requires std::is_invocable_v<Cleaner, T>
    const T& RAII<T, Cleaner>::Object() const noexcept {
        return obj_;
    }

    MappedReadOnlyFile::MappedReadOnlyFile() noexcept = default;

    MappedReadOnlyFile::~MappedReadOnlyFile() noexcept {
        Unmap();
    }

    std::byte* MappedReadOnlyFile::Map(std::string path) {
        path_ = std::move(path);
        if (stat(path_.c_str(), &stat_) != 0) {
            ThrowLastSystemError();
        }
        int fd = open(path_.c_str(), O_RDONLY);
        if (fd == -1) {
            ThrowLastSystemError();
        }
        data_ = static_cast<std::byte*>(mmap(nullptr, stat_.st_size, PROT_READ, MAP_PRIVATE, fd, 0));
        close(fd);
        if (data_ == MAP_FAILED) {
            ThrowLastSystemError();
        }
        Check();
        return data_;
    }

    void MappedReadOnlyFile::Unmap() noexcept {
        if (data_ != nullptr && data_ != MAP_FAILED) {
            munmap(data_, stat_.st_size);
            data_ = nullptr;
        }
    }

    std::size_t MappedReadOnlyFile::Size() const noexcept {
        return stat_.st_size;
    }

    std::byte* MappedReadOnlyFile::Data() const noexcept {
        return data_;
    }

    std::string_view MappedReadOnlyFile::Path() const noexcept {
        return path_;
    }

    void MappedReadOnlyFile::Check() {
        if (data_ == nullptr || data_ == MAP_FAILED) {
            throw std::runtime_error("Failed to map file");
        }
    }
}
